1	use std::collections::HashMap;
2	
3	/// Added to every premium, whatever the policy contains.
4	const PROCESSING_FEE: u64 = 5;
5	
6	/// Charged once per component, uniformly for every component type.
7	const COMPONENT_BASE_PREMIUM: u64 = 25;
8	
9	/// Components alike in type are offered as a building block at this premium.
10	const BUILDING_BLOCK_BASE_PREMIUM: u64 = 60;
11	
12	/// A cursed item adds this percentage of its base premium as risk surcharge.
13	const CURSE_PERCENT: u64 = 50;
14	
15	/// A highly enchanted item adds this percentage of its base premium as risk
16	/// surcharge.
17	const HIGH_ENCHANTMENT_PERCENT: u64 = 30;
18	
19	/// An item counts as highly enchanted from this enchantment level upwards.
20	const HIGH_ENCHANTMENT_LEVEL: u64 = 5;
21	
22	/// Every quote treats each item as a first insurance, surcharged by this
23	/// percentage of the policy base premium.
24	const FIRST_INSURANCE_PERCENT: u64 = 10;
25	
26	/// A building block is offered for exactly this many alike components.
27	const BUILDING_BLOCK_SIZE: usize = 3;
28	
29	/// The kind of magical item the MHPCO insures.
30	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
31	pub enum ItemType {
32	    Sword,
33	    Amulet,
34	    Staff,
35	    Potion,
36	    Rune,
37	    Moonstone,
38	}
39	
40	/// An item a customer wishes to insure.
41	pub struct Item {
42	    pub item_type: ItemType,
43	    /// A cursed item carries a risk surcharge.
44	    pub cursed: bool,
45	    /// How strongly the item is enchanted. A highly enchanted item carries a
46	    /// risk surcharge; a component has no enchantment.
47	    pub enchantment: u64,
48	}
49	
50	/// Computes the premium in whole G for the items a customer wishes to insure.
51	/// The MHPCO charges the policy base premium, adjusts it by the item-scoped
52	/// and the policy-scoped modifiers, and adds the processing fee at the very end.
53	pub fn quote(items: &[Item]) -> u64 {
54	    let base = policy_base_premium(items);
55	    base + item_surcharges(items) + policy_surcharges(base) + PROCESSING_FEE
56	}
57	
58	/// The modifiers the MHPCO applies to the base premium of an individual
59	/// affected item, summed over the policy.
60	fn item_surcharges(items: &[Item]) -> u64 {
61	    items.iter().map(risk_surcharge).sum()
62	}
63	
64	/// The modifiers the MHPCO applies to the policy base premium as a whole.
65	/// Every quote treats each item as a first insurance, whatever the customer's
66	/// history, so the initial assessment surcharge is charged on every policy.
67	///
68	/// Every example so far divides exactly. The MHPCO keeps intermediate amounts
69	/// as fractions and rounds only the final premium, so a modifier whose
70	/// percentage does not divide evenly needs a fractional amount here rather
71	/// than this truncating division.
72	fn policy_surcharges(policy_base: u64) -> u64 {
73	    policy_base * FIRST_INSURANCE_PERCENT / 100
74	}
75	
76	/// The risk surcharge in G an item adds to its own base premium: the MHPCO
77	/// charges a cursed item a percentage of what it would otherwise cost.
78	fn risk_surcharge(item: &Item) -> u64 {
79	    let mut percent = 0;
80	    if item.cursed {
81	        percent += CURSE_PERCENT;
82	    }
83	    if item.enchantment >= HIGH_ENCHANTMENT_LEVEL {
84	        percent += HIGH_ENCHANTMENT_PERCENT;
85	    }
86	    item_base_premium(item) * percent / 100
87	}
88	
89	/// The policy base premium in G: the sum of all item base premiums, before
90	/// any modifier is applied. Main items are priced one by one; components are
91	/// priced by set of alike components, so that a building block can apply.
92	pub fn policy_base_premium(items: &[Item]) -> u64 {
93	    let main_items: u64 = items
94	        .iter()
95	        .filter(|item| !is_component(item.item_type))
96	        .map(item_base_premium)
97	        .sum();
98	    main_items + components_base_premium(items)
99	}
100	
101	/// The base premium in G for every component on the policy: the MHPCO prices
102	/// each set of components alike in type on its own.
103	fn components_base_premium(items: &[Item]) -> u64 {
104	    alike_component_counts(items)
105	        .into_values()
106	        .map(alike_base_premium)
107	        .sum()
108	}
109	
110	/// How many components the policy carries in each set of alike components.
111	/// Components count as alike when they are of exactly the same type: a rune
112	/// and a moonstone are never alike, however similar they look.
113	fn alike_component_counts(items: &[Item]) -> HashMap<ItemType, usize> {
114	    let mut counts: HashMap<ItemType, usize> = HashMap::new();
115	    for item in items.iter().filter(|item| is_component(item.item_type)) {
116	        *counts.entry(item.item_type).or_default() += 1;
117	    }
118	    counts
119	}
120	
121	/// The base premium in G for one set of components alike in type: the MHPCO
122	/// offers a building block wherever the customer brings exactly three.
123	fn alike_base_premium(alike: usize) -> u64 {
124	    if alike == BUILDING_BLOCK_SIZE {
125	        BUILDING_BLOCK_BASE_PREMIUM
126	    } else {
127	        alike as u64 * COMPONENT_BASE_PREMIUM
128	    }
129	}
