131	/// Components, such as runes and moonstones, are the items the MHPCO prices
132	/// uniformly and offers as building blocks.
133	fn is_component(item_type: ItemType) -> bool {
134	    matches!(item_type, ItemType::Rune | ItemType::Moonstone)
135	}
