137	/// What the MHPCO charges for one item on its own, straight from the price
138	/// list. A component priced inside a building block is charged by the group
139	/// instead, through `components_base_premium`.
140	fn item_base_premium(item: &Item) -> u64 {
141	    match item.item_type {
142	        ItemType::Sword => 100,
143	        ItemType::Amulet => 60,
144	        ItemType::Staff => 80,
145	        ItemType::Potion => 40,
146	        ItemType::Rune | ItemType::Moonstone => COMPONENT_BASE_PREMIUM,
147	    }
148	}
