cp src/lib.rs /tmp/lib.rs.trial1.bak && python3 - <<'PY'
import io
p = 'src/lib.rs'
s = io.open(p, encoding='utf-8').read()

old = '''/// The risk surcharge in G an item adds to its own base premium: the MHPCO
/// charges a cursed item a percentage of what it would otherwise cost.
fn risk_surcharge(item: &Item) -> u64 {
    let mut percent = 0;
    if item.cursed {
        percent += CURSE_PERCENT;
    }
    if item.enchantment >= HIGH_ENCHANTMENT_LEVEL {
        percent += HIGH_ENCHANTMENT_PERCENT;
    }
    item_base_premium(item) * percent / 100
}
'''

new = '''/// The risk surcharge in G an item adds to its own base premium. The MHPCO
/// lists its risks one by one and charges every risk an item carries, so the
/// surcharges of all applicable risks stack.
///
/// Every rate so far divides the base premium exactly. The MHPCO keeps
/// intermediate amounts as fractions and rounds only the final premium, so a
/// rate that does not divide evenly needs a fractional amount per risk rather
/// than this truncating division.
fn risk_surcharge(item: &Item) -> u64 {
    let base = item_base_premium(item);
    curse_surcharge(item, base) + high_enchantment_surcharge(item, base)
}

/// What the MHPCO adds for a cursed item: a percentage of what the item would
/// otherwise cost.
fn curse_surcharge(item: &Item, item_base: u64) -> u64 {
    if item.cursed {
        item_base * CURSE_PERCENT / 100
    } else {
        0
    }
}

/// What the MHPCO adds for a highly enchanted item: a percentage of what the
/// item would otherwise cost.
fn high_enchantment_surcharge(item: &Item, item_base: u64) -> u64 {
    if is_highly_enchanted(item) {
        item_base * HIGH_ENCHANTMENT_PERCENT / 100
    } else {
        0
    }
}

/// An item counts as highly enchanted from the threshold enchantment level
/// upwards: the MHPCO reads its thresholds inclusively.
fn is_highly_enchanted(item: &Item) -> bool {
    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
}
'''

assert old in s
s = s.replace(old, new)
io.open(p, 'w', encoding='utf-8').write(s)
print("patched")
